package net.hivel.islandsrpg.gui;
import net.hivel.islandsrpg.IslandsRPGPlugin; import org.bukkit.entity.Player; import org.bukkit.event.inventory.InventoryClickEvent;
public class GuiManager { public final MainMenuGui main; public final StatsGui stats; public final IslandsGui islands; public final QuestsGui quests; public final ProfileGui profile; public final WeaponsGui weapons; public GuiManager(IslandsRPGPlugin p){main=new MainMenuGui(p); stats=new StatsGui(p); islands=new IslandsGui(p); quests=new QuestsGui(p); profile=new ProfileGui(p); weapons=new WeaponsGui(p);} public void openMain(Player p){main.open(p);} public void handle(InventoryClickEvent e){String t=e.getView().getTitle(); if(t.contains("ɪꜱʟᴀɴᴅꜱ ʀᴘɢ"))main.click(e); else if(t.contains("ꜱᴛᴀᴛꜱ"))stats.click(e); else if(t.contains("ɪꜱʟᴀɴᴅꜱ")&&!t.contains("ʀᴘɢ"))islands.click(e); else if(t.contains("ǫᴜᴇꜱᴛꜱ"))quests.click(e); else if(t.contains("ᴘʀᴏꜰɪʟᴇ")||t.contains("ᴡᴇᴀᴘᴏɴꜱ"))e.setCancelled(true);} }
